const { ShopifyClientError } = require('../errors');

const THEMES_QUERY = `
  query {
    themes(first: 50) {
      edges {
        node {
          id
          name
          role
        }
      }
    }
  }
`;

const THEME_FILES_QUERY = `
  query themeFiles($themeId: ID!, $cursor: String, $filenames: [String!]) {
    theme(id: $themeId) {
      id
      name
      role
      files(first: 250, after: $cursor, filenames: $filenames) {
        edges {
          node {
            filename
            body {
              ... on OnlineStoreThemeFileBodyText {
                content
              }
              ... on OnlineStoreThemeFileBodyBase64 {
                contentBase64
              }
            }
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  }
`;

const THEME_FILES_UPSERT_MUTATION = `
  mutation themeFilesUpsert($themeId: ID!, $files: [OnlineStoreThemeFilesUpsertFileInput!]!) {
    themeFilesUpsert(themeId: $themeId, files: $files) {
      upsertedThemeFiles {
        filename
      }
      userErrors {
        field
        message
        code
      }
    }
  }
`;

const THEME_FILES_DELETE_MUTATION = `
  mutation themeFilesDelete($themeId: ID!, $files: [String!]!) {
    themeFilesDelete(themeId: $themeId, files: $files) {
      deletedThemeFiles {
        filename
      }
      userErrors {
        field
        message
        code
      }
    }
  }
`;

function throwOnUserErrors(operation, userErrors) {
  if (!userErrors || userErrors.length === 0) {
    return;
  }

  throw new ShopifyClientError(`${operation} failed`, {
    code: 'SHOPIFY_USER_ERROR',
    details: {
      userErrors
    }
  });
}

function normalizeFileNode(node) {
  const textContent = node && node.body && typeof node.body.content === 'string'
    ? node.body.content
    : null;
  const base64Content = node && node.body && typeof node.body.contentBase64 === 'string'
    ? node.body.contentBase64
    : null;

  return {
    filename: node.filename,
    content: textContent,
    contentBase64: base64Content,
    isBase64: Boolean(base64Content && textContent === null)
  };
}

function createThemesClient({ graphql }) {
  const cache = {
    themes: null,
    publishedTheme: undefined,
    filesByThemeId: new Map()
  };

  async function list() {
    if (cache.themes) {
      return cache.themes;
    }

    const data = await graphql(THEMES_QUERY);
    const themes = (data.themes && data.themes.edges
      ? data.themes.edges.map((edge) => edge.node)
      : []);

    cache.themes = themes;
    return themes;
  }

  async function getPublishedTheme() {
    if (cache.publishedTheme !== undefined) {
      return cache.publishedTheme;
    }

    const themes = await list();
    const publishedTheme =
      themes.find((theme) => theme.role === 'MAIN') || null;

    cache.publishedTheme = publishedTheme;
    return publishedTheme;
  }

  async function resolveThemeId(themeId) {
    if (themeId) {
      return themeId;
    }

    const publishedTheme = await getPublishedTheme();
    if (!publishedTheme) {
      throw new ShopifyClientError('Published theme not found', {
        code: 'MISSING_PUBLISHED_THEME'
      });
    }

    return publishedTheme.id;
  }

  async function listFiles(themeId, options = {}) {
    const resolvedThemeId = await resolveThemeId(themeId);
    const explicitFilenames = Array.isArray(options.filenames) && options.filenames.length > 0
      ? [...new Set(options.filenames)]
      : null;
    const cacheKey = explicitFilenames ? null : resolvedThemeId;

    if (cacheKey && cache.filesByThemeId.has(cacheKey)) {
      return cache.filesByThemeId.get(cacheKey);
    }

    const files = [];
    let cursor = null;
    let hasNextPage = true;

    while (hasNextPage) {
      const data = await graphql(THEME_FILES_QUERY, {
        themeId: resolvedThemeId,
        cursor,
        filenames: explicitFilenames
      });
      const connection = data.theme && data.theme.files;
      const edges = connection && connection.edges ? connection.edges : [];
      files.push(...edges.map((edge) => normalizeFileNode(edge.node)));
      hasNextPage = Boolean(connection && connection.pageInfo && connection.pageInfo.hasNextPage);
      cursor = connection && connection.pageInfo ? connection.pageInfo.endCursor : null;

      if (explicitFilenames) {
        break;
      }
    }

    if (cacheKey) {
      cache.filesByThemeId.set(cacheKey, files);
    }

    return files;
  }

  async function readFiles(themeId, filenames) {
    if (!Array.isArray(filenames) || filenames.length === 0) {
      return [];
    }

    return listFiles(themeId, { filenames });
  }

  async function upsertFiles(themeId, files) {
    const resolvedThemeId = await resolveThemeId(themeId);
    const data = await graphql(THEME_FILES_UPSERT_MUTATION, {
      themeId: resolvedThemeId,
      files: (files || []).map((file) => ({
        filename: file.filename,
        body: file.isBase64
          ? { type: 'BASE64', value: file.contentBase64 }
          : { type: 'TEXT', value: file.content || '' }
      }))
    });

    throwOnUserErrors('Theme files upsert', data.themeFilesUpsert.userErrors);
    cache.filesByThemeId.delete(resolvedThemeId);
    return data.themeFilesUpsert.upsertedThemeFiles || [];
  }

  async function deleteFiles(themeId, filenames) {
    if (!Array.isArray(filenames) || filenames.length === 0) {
      return [];
    }

    const resolvedThemeId = await resolveThemeId(themeId);
    const data = await graphql(THEME_FILES_DELETE_MUTATION, {
      themeId: resolvedThemeId,
      files: filenames
    });

    throwOnUserErrors('Theme files delete', data.themeFilesDelete.userErrors);
    cache.filesByThemeId.delete(resolvedThemeId);
    return data.themeFilesDelete.deletedThemeFiles || [];
  }

  return {
    list,
    getPublishedTheme,
    resolveThemeId,
    listFiles,
    readFiles,
    upsertFiles,
    deleteFiles
  };
}

module.exports = {
  createThemesClient,
  THEMES_QUERY,
  THEME_FILES_QUERY,
  THEME_FILES_UPSERT_MUTATION,
  THEME_FILES_DELETE_MUTATION
};
